/* 💭 顶栏根容器：设定整体布局框架与底色。
   💭 采用 Flex 布局并设置 justify-content: center，为中间的接收方备注名提供完全居中的空间。
   💭 min-height: 62px 控制顶栏总高度。
   💭 background-color 依据设定应用为 #F1F1F1。 */
.sully-chat-header {
  background-color: #F1F1F1 !important;
  background-image: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: relative !important;
  min-height: 62px !important;
  padding: 0 16px !important;
  border: none !important;
  box-shadow: 0 1px 2px rgba(0,0,0,0.03) !important;
}

/* 💭 核心隔离机制：阻止原本外层容器霸占多余宽度影响居中对齐。
   💭 将顶栏内容部的所有包裹层限定为真实宽度（flex: 0 0 auto，width: auto）。
   💭 通过 position: static 破除定位墙，让需要绝对定位的子元素正常起效。 */
.sully-chat-header > div,
.sully-chat-header > div > div {
  flex: 0 0 auto !important;
  width: auto !important;
  position: static !important;
  transform: none !important;
}

/* 💭 顶栏头像与点击功能转移：将原本隐藏的发送方/接收方头像改造为隐形的点击热区，覆盖在备注名上方。
   💭 display: block 配合 opacity: 0 确保其完全透明不可见，但保留其原有的 JS 点击事件。
   💭 position: absolute 与 left: 50% 将其精准定位到屏幕横向中央。
   💭 width: 160px 与 height: 40px 提供充足的触控面积，完全覆盖备注名。
   💭 z-index: 50 确保其层级高于备注文字，巧妙实现点击备注即触发“切换会话”的功能。 */
.sully-chat-avatar {
  display: block !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, calc(-50% + 6px)) !important;
  width: 160px !important;
  max-width: 50vw !important;
  height: 40px !important;
  opacity: 0 !important;
  z-index: 50 !important;
  cursor: pointer !important;
  border: none !important;
  background: transparent !important;
}

/* 💭 返回按钮容器：绝对定位固定在左侧。
   💭 left: 12px 减小边距，让图标整体偏左，为圆条贴近提供空间。
   💭 background-size: 28px !important 将返回箭头的视觉尺寸放大。
   💭 width 与 height 设为 40px，在增大图标的同时保证足够的触控热区。 */
.sully-chat-back {
  position: absolute !important;
  left: 12px !important;
  top: 50% !important;
  transform: translateY(calc(-50% + 4px)) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 40px !important;
  height: 40px !important;
  background-color: transparent !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%231A1A1A' stroke-width='1.3' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 18 9 12 15 6'></polyline></svg>") !important;
  background-size: 28px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  border: none !important;
  box-shadow: none !important;
  z-index: 30 !important;
}

/* 💭 隐藏原有的返回 SVG 图标。 */
.sully-chat-back svg {
  display: none !important;
}

/* 💭 触发按钮（右侧三个点容器）：绝对定位固定在右侧。
   💭 SVG 内部圆点半径为 r='1.2'，使其视觉上显得细致。
   💭 background-size: 26px !important 稍微缩小整体图标尺寸。
   💭 right: 12px 确保两边距离对称。 */
.sully-chat-trigger {
  position: absolute !important;
  right: 12px !important;
  top: 50% !important;
  transform: translateY(calc(-50% + 4px)) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 40px !important;
  height: 40px !important;
  background-color: transparent !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%231A1A1A'><circle cx='5' cy='12' r='1.2'/><circle cx='12' cy='12' r='1.2'/><circle cx='19' cy='12' r='1.2'/></svg>") !important;
  background-size: 26px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  border: none !important;
  box-shadow: none !important;
  z-index: 30 !important;
}

/* 💭 隐藏原有的触发 SVG 图标。 */
.sully-chat-trigger svg {
  display: none !important;
}

/* 💭 接收方角色名称：在破除了外层干扰后，完全居中排列。
   💭 transform: translateY(6px) !important 进一步增加下移量，实现稍微向下偏移的视觉效果。
   💭 color 设定为 #1A1A1A 与全局图标字色保持高度统一。 */
.sully-chat-name {
  position: relative !important;
  transform: translateY(6px) !important;
  text-align: center !important;
  font-weight: 600 !important;
  font-size: 16px !important;
  color: #1A1A1A !important;
  margin: 0 !important;
  white-space: nowrap !important;
  max-width: 40vw !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  pointer-events: none !important;
}

/* 💭 状态区域：原本包裹 Token 等元素的容器。
   💭 同步下移 translateY(6px)，目前内部元素已隐藏，仅作结构保留。 */
.sully-chat-status {
  position: static !important;
  display: flex !important;
  align-items: center !important;
  transform: translateY(6px) !important;
  margin-left: 4px !important;
  pointer-events: none !important;
  width: auto !important;
  padding: 0 !important;
}

/* 💭 隐藏状态区域内的所有非必要子元素。 */
.sully-chat-status > *:not(.sully-chat-buffs) {
  display: none !important;
}

/* 💭 Token 用量标签：执行隐藏操作，不再显示 Token 数值。 */
.sully-chat-token {
  display: none !important;
}

/* 💭 情绪徽章 (Buffs) 容器：作为承载数字的灰色长条底座。
   💭 left: 38px !important 控制其强力贴近左侧返回图标。
   💭 padding: 3px 8px !important 增加内边距，使胶囊圆条整体更饱满。
   💭 z-index: 20 放在图标之下，避免阻挡返回按钮的触控点击。 */
.sully-chat-buffs {
  position: absolute !important;
  left: 38px !important;
  top: 50% !important;
  transform: translateY(calc(-50% + 4px)) !important;
  z-index: 20 !important;
  pointer-events: auto !important;
  display: flex !important;
  align-items: center !important;
  gap: 0 !important;
  margin: 0 !important;
  width: auto !important;
  background: #E2E2E2 !important;
  border-radius: 9999px !important;
  padding: 3px 8px !important;
  counter-reset: buff-counter !important;
}

/* 💭 情绪徽章单体按钮：消除容器宽度限制与间距。
   💭 margin: 0 -0.8px !important 利用负边距让独立数字紧密聚拢。 */
.sully-chat-buffs button {
  counter-increment: buff-counter !important;
  font-size: 0 !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  margin: 0 -0.8px !important;
  min-width: 0 !important;
  width: auto !important;
  height: auto !important;
  box-shadow: none !important;
  color: transparent !important;
}

/* 💭 防止原有结构内的其他标签产生残留体积。 */
.sully-chat-buffs button * {
  display: none !important;
}

/* 💭 情绪徽章数字：展示纯黑色、紧凑且遵循原生规范的系统字体。
   💭 font-weight: 500 !important 将字重微调至中等（Medium），减轻粗黑感，使其视觉上更柔和。
   💭 font-size: 15px !important 保持大数字尺寸。
   💭 letter-spacing: -0.8px !important 配合字体字重加强字间距收缩。 */
.sully-chat-buffs button::after {
  content: counter(buff-counter) !important;
  color: #1A1A1A !important;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro", "Inter", "PingFang SC", sans-serif !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
  letter-spacing: -0.8px !important;
}

/* 💭 面板显示区域：将展开的详情面板强行升级为 fixed 视口定位。
   💭 避免面板弹出时被外围父级结构裁剪截断。 */
.sully-chat-header .absolute.top-full.z-40,
.sully-chat-header .absolute.top-full.z-50 {
  position: fixed !important;
  top: 66px !important;
  left: 16px !important;
  right: 16px !important;
  margin-top: 0 !important;
  z-index: 9999 !important;
}

/* 💭 聊天室根容器：设定聊天室没有背景图时的默认全局底色。
   💭 background-color: #F1F1F1 作为基础底色存在，呈现偏白的浅灰视觉。
   💭 移除强制优先级，确保该设置不会阻断系统或用户自定义的内联背景图/背景色的覆盖应用。 */
.sully-chat-root {
  background-color: #F1F1F1;
}

/* ====================================
   底栏基础结构与输入框区域
   ===================================== */

/* 💭 底栏根容器：设定整体布局框架与底色。
   💭 background-color: #F9F9F9 !important 将底色提亮偏白。
   💭 backdrop-filter: none 取消毛玻璃效果，呈现纯净底色。
   💭 border-top 增加淡色顶部分割线区分区域。
   💭 box-shadow: none !important 彻底移除底栏和聊天室背景衔接处的任何多余投影。 */
.sully-chat-inputbar {
  background-color: #F9F9F9 !important;
  background-image: none !important;
  backdrop-filter: none !important;
  border-top: 1px solid #EAEAEA !important;
  box-shadow: none !important;
}

/* 💭 输入行整体容器：调节底栏高度与上下留白。
   💭 padding: 10px 6px 8px 6px !important (上 右 下 左) 将上边距增加至 8px，为内部顶部留出空白呼吸空间，下边距为 8px 使底栏整体适度增高。
   💭 gap: 4px !important 维持横向紧凑的模块间隙。 */
.sully-chat-inputbar > .p-3.px-4.flex.gap-3.items-end.relative {
  padding: 8px 6px 8px 6px !important;
  gap: 4px !important;
}

/* 💭 输入框包裹容器：破除原有视觉束缚，为内部真实输入框提供自由空间。
   💭 border-radius: 0 !important 与 overflow: visible !important 强行阻止原生外层容器对内部 textarea 的裁切。
   💭 box-shadow: none !important 移除外层包裹的任何可能阴影。 */
.sully-chat-inputbar .flex-1.min-w-0.flex.items-center.px-1,
.sully-chat-inputbar .flex-1.min-w-0.flex.items-center.px-1:focus-within {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;
  gap: 2px !important;
  overflow: visible !important;
}

/* 💭 独立方圆角输入框：纯净无边框的白色输入区。
   💭 border: none !important 彻底移除原有的线框，实现极致极简。
   💭 background-color: #FFFFFF !important 确保背景为纯白。
   💭 border-radius: 4px !important 设为极小的方角（微信风格）。
   💭 box-shadow: none !important 彻底移除阴影！
   💭 padding: 7px 36px 7px 10px !important 右侧特意留空给麦克风占位。
   💭 麦克风图标：stroke='%23999999' 颜色偏灰，stroke-width='2' 线条加粗。 */
.sully-chat-inputbar textarea {
  flex: 1 !important;
  background-color: #FFFFFF !important;
  border-radius: 4px !important;
  border: none !important;
  box-shadow: none !important;
  padding: 7px 10px !important;
  color: #1A1A1A !important;
  margin-bottom: 0 !important;
}

/* 💭 输入框占位符：彻底隐藏默认提示文字。 */
.sully-chat-inputbar textarea::placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

/* 💭 左侧动作按钮（扇形波纹加号）：保持左侧紧凑。 */
.sully-chat-inputbar > .p-3.px-4 > button:first-child {
  width: 36px !important;
  height: 36px !important;
  min-width: 36px !important;
  padding: 0 !important;
  margin-bottom: 0 !important;
  background-color: transparent !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23333333' stroke-width='1.3' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='10'/><line x1='12' y1='8' x2='12' y2='16'/><line x1='8' y1='12' x2='16' y2='12'/></svg>") !important;
  background-size: 28px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.sully-chat-inputbar > .p-3.px-4 > button:first-child svg {
  display: none !important;
}

/* 💭 表情按钮（笑脸）：右移操作，贴紧外侧发送按钮，空出位给拉长的输入框。 */
.sully-chat-inputbar .p-2.shrink-0 {
  align-self: flex-end !important;
  width: 36px !important;
  height: 36px !important;
  padding: 0 !important;
  margin-bottom: 0 !important;
  margin-right: -4px !important;
  background-color: transparent !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23333333' stroke-width='1.3' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='10'/><circle cx='8.5' cy='8.5' r='1.5' fill='%23333333' stroke='none'/><circle cx='15.5' cy='8.5' r='1.5' fill='%23333333' stroke='none'/><path d='M 6.5 12.5 a 5.5 5.5 0 0 0 11 0 H 6.5 z' fill='none' stroke='%23333333' stroke-width='1.3' stroke-linejoin='round'/></svg>") !important;
  background-size: 28px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.sully-chat-inputbar .p-2.shrink-0 svg {
  display: none !important;
}

/* 💭 发送按钮（圆圈加号）：锁定未激活状态不发灰。 */
.sully-chat-inputbar > .p-3.px-4 > button:last-child {
  width: 36px !important;
  height: 36px !important;
  min-width: 36px !important;
  padding: 0 !important;
  margin-bottom: 0 !important;
  opacity: 1 !important;
  filter: none !important;
  background-color: transparent !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23333333' stroke-width='1.3' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='10'/><line x1='12' y1='8' x2='12' y2='16'/><line x1='8' y1='12' x2='16' y2='12'/></svg>") !important;
  background-size: 28px !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.sully-chat-inputbar > .p-3.px-4 > button:last-child svg,
.sully-chat-inputbar > .p-3.px-4 > button:last-child span {
  display: none !important;
}

/* ============================================================
   仿微信简约风格：底部各大面板区域（表情/动作/设置等）美化
   ============================================================ */

/* 💭 面板总容器：提供微信标志性的浅灰大背景底色。 */
.sully-chat-panel {
  background: #F7F7F7 !important;
  border-top: 1px solid #EAEAEA !important;
  box-shadow: none !important;
}

/* 💭 表情面板：顶部横向分类栏。 */
.sully-chat-panel .h-10.flex.items-center.px-2.gap-2.overflow-x-auto.no-scrollbar.shrink-0 {
  background: #F7F7F7 !important;
  border-bottom: 1px solid transparent !important;
}

/* 💭 表情分类按钮（常规与激活态统一净化）。 */
.sully-chat-panel .px-3.py-1.text-xs.rounded-full.whitespace-nowrap {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: #555555 !important;
  font-weight: 400 !important;
}
/* 拦截带 font-bold 的激活项，赋予微信绿特征或极简黑 */
.sully-chat-panel .px-3.py-1.text-xs.rounded-full.font-bold {
  color: #07C160 !important; /* 微信主题绿 */
  background: #FFFFFF !important; /* 白色底作为激活高亮 */
  border-radius: 6px !important;
  font-weight: 500 !important;
}

/* 💭 分类栏右侧工具按钮（添加分类等）。 */
.sully-chat-panel .w-6.h-6.rounded-full.flex.items-center.justify-center.shrink-0,
.sully-chat-panel .w-6.h-6.rounded-full.flex.items-center.justify-center.transition-colors.shadow-sm.pointer-events-auto {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: #777777 !important;
}

/* 💭 独立表情小项（卡片阵列）：去除白底框。 */
.sully-chat-panel .bg-white.rounded-2xl.p-2.shadow-sm.relative.active\:scale-95.transition-transform.select-none.flex.flex-col.items-center {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
}

/* 💭 表情包面板 - 多选选中高亮层：改为微信风格淡绿色。 */
.sully-chat-panel .absolute.inset-0.bg-blue-500\/20.rounded-2xl.pointer-events-none.border-2.border-blue-500 {
  background-color: rgba(7, 193, 96, 0.15) !important;
  border-color: #07C160 !important;
}

/* 💭 表情名称文字。 */
.sully-chat-panel .text-\[9px\].truncate.w-full.text-center.mt-0\.5.leading-tight.pointer-events-none {
  color: #AAAAAA !important;
  font-weight: 300 !important;
}

/* 💭 特殊表情卡：第一格的“添加表情”或“批量删除”块，去粗取精，极致简约。
   💭 background: transparent !important 移除原有灰底，融入大背景。
   💭 border: 1px dashed #D0D0D0 !important 将原有 2px 粗边框改为 1px 极细淡色虚线。
   💭 border-radius: 8px !important 取消大圆角，改为硬朗的简约方圆角。
   💭 color: #999999 !important 淡化内部加号颜色。 */
.sully-chat-panel .aspect-square.rounded-2xl.border-2.border-dashed.flex.items-center.justify-center.text-2xl {
  background: transparent !important;
  border: 1px dashed #D0D0D0 !important;
  border-radius: 8px !important;
  color: #999999 !important;
}

/* 💭 表情面板分页控件容器：文字淡化，融入整体极简风格。 */
.sully-chat-panel .py-3.flex.items-center.justify-center.gap-3.text-\[10px\] {
  color: #999999 !important;
  font-size: 11px !important;
}

/* 💭 表情面板翻页按钮（左右箭头）：去除冗余线框。 */
.sully-chat-panel .w-8.h-7.rounded-full.border.border-current\/20.disabled\:opacity-30.active\:scale-95 {
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: #666666 !important;
}

/* 💭 动作面板（+号菜单）：极简白块 + 统一深灰色图标配色。
   💭 background: #FFFFFF !important 统一图标容器白底。
   💭 border-radius: 12px !important 方圆角风格。 */
.sully-chat-panel .w-14.h-14.rounded-2xl.flex.items-center.justify-center.shadow-sm.border,
.sully-chat-panel .w-14.h-14.shrink-0.rounded-2xl.grid.place-items-center.transition-transform.group-active\:scale-95 {
  background: #FFFFFF !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 12px !important;
}

/* 💭 动作面板图标尺寸缩小：限定于前两页（位于 grid 布局内的图标方块）。
   💭 width: 48px !important; height: 48px !important 将外围白底方块适当缩小。 */
.sully-chat-panel .grid.grid-cols-4 .w-14.h-14 {
  width: 48px !important;
  height: 48px !important;
