/* ============================================================
   引用/回复（Reply/Quote）与手势指示器美化
   ============================================================ */

/* 💭 核心排版修正：为包含引用条的气泡底部精准撑开空间。
   💭 引用小条高度微调为 22px（为英文字母下半部分留出空间），顶部外边距为 4px，总计溢出气泡底部 26px。
   💭 增加 26px 的下边距，刚好抵消小条的体积，使真实间距保持 11px。 */
.sully-bubble-ai:has(.relative.z-10.mb-1),
.sully-bubble-user:has(.relative.z-10.mb-1) {
  margin-bottom: 26px !important;
  overflow: visible !important;
}

/* 💭 引用条容器：Flexbox 弹性盒子布局。
   💭 height: 22px !important; 高度稍微增加 2px，防止彻底卡死文字的上下边界。
   💭 align-items: center !important; 保持绝对垂直居中。 */
.sully-chat-message-content .relative.z-10.mb-1 {
  position: absolute !important;
  top: 100% !important;
  margin-top: 4px !important;
  margin-bottom: 0 !important;
  background: #E0E0E0 !important;
  border: none !important;
  border-radius: 2px !important;
  padding: 0 6px !important;
  height: 22px !important;
  opacity: 1 !important;
  width: max-content !important;
  max-width: 180px !important;
  box-sizing: border-box !important;

  /* 开启 Flex 居中布局 */
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 0 !important;
}

/* 💭 动态对齐：接收方（AI）的小条靠左对齐，发送方（User）靠右对齐。 */
.sully-bubble-ai .relative.z-10.mb-1 {
  left: 0 !important;
}
.sully-bubble-user .relative.z-10.mb-1 {
  right: 0 !important;
}

/* 💭 回复对象的备注名：修复字母 'y' 等下半部被遮挡的问题。
   💭 line-height: normal !important; 恢复正常的行高，让英文字母的下延部分（Descender）有足够的渲染空间。
   💭 transform: none !important; 移除之前强制下移的位移，依靠 Flex 自然居中。 */
.sully-chat-message-content .relative.z-10.mb-1 .font-bold.opacity-90.truncate {
  display: block !important;
  flex-shrink: 0 !important;
  font-weight: 400 !important;
  color: #666666 !important;
  font-size: 10px !important;
  line-height: normal !important;
  transform: none !important;
}

/* 💭 在备注名后方利用伪元素动态注入一个冒号，实现“回复对象：”的格式。 */
.sully-chat-message-content .relative.z-10.mb-1 .font-bold.opacity-90.truncate::after {
  content: "：" !important;
}

/* 💭 引用内容文字：同样修复行高，防止字母被裁切。 */
.sully-chat-message-content .relative.z-10.mb-1 .truncate.italic {
  display: block !important;
  flex-shrink: 1 !important;
  font-style: normal !important;
  color: #777777 !important;
  font-size: 10px !important;
  line-height: normal !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  transform: none !important;
}

/* ============================================================
   右滑回复手势指示器（Swipe Reply Indicator）
   ============================================================ */

/* 💭 指示器容器：去除所有发光、圆底和阴影，变为无框状态。
   💭 right: -24px !important; 缩小右侧距离，使其自动贴紧气泡边缘。
   💭 width & height 缩小，适配极简的图标尺寸。 */
.sully-chat-message-content .absolute.-right-10.top-1\/2.-translate-y-1\/2 {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  right: -24px !important;
  width: 20px !important;
  height: 20px !important;
}

/* 💭 拦截就绪状态（拖拽超过阈值触发）：强制去除高亮背景与阴影，保持极简无框。 */
.sully-chat-message-content .absolute.-right-10.bg-indigo-500 {
  background: transparent !important;
  box-shadow: none !important;
}

/* 💭 隐藏原生的箭头 SVG 图标。 */
.sully-chat-message-content .absolute.-right-10 svg {
  display: none !important;
}

/* 💭 注入新的灰色小弯角箭头：使用伪元素绘制线条极简的回复弯角箭头。
   💭 stroke='%23999999' 保持与系统提示相同的灰色调，不发光、不高亮。 */
.sully-chat-message-content .absolute.-right-10::before {
  content: "" !important;
  display: block !important;
  width: 16px !important;
  height: 16px !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23999999' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M9 14 4 9l5-5'/><path d='M4 9h10.5a5.5 5.5 0 0 1 5.5 5.5v.5'/></svg>") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ============================================================
   输入框上方引用预览条（Reply Preview Bar）美化
   ============================================================ */

/* 💭 监听预览条的存在状态，为整个输入行容器增加底部内边距。
   💭 此操作可预留出 36px 的物理空间，使加号、输入框与发送按钮作为一个整体同步上移。 */
.sully-chat-root:has(.flex.items-center.justify-between.bg-slate-50.border-b.border-slate-200.text-slate-500) .sully-chat-inputbar > .p-3.px-4.flex.gap-3.items-end.relative {
  padding-bottom: 36px !important;
}

/* 💭 为输入行增加过渡动画，确保在引用条出现和取消时，整体上移和复位过程保持平滑。 */
.sully-chat-inputbar > .p-3.px-4.flex.gap-3.items-end.relative {
  transition: padding-bottom 0.2s ease-out !important;
}

/* 💭 引用条整体容器定位：使用绝对定位将其放置在输入框下方腾出的空间内。
   💭 left 设定为 46px（6px 内边距 + 36px 加号 + 4px 间距），与输入框左侧对齐。
   💭 right 设定为 78px（右侧原 46px + 32px 表情包占位），避开表情包宽度，精准对齐文字输入区。
   💭 bottom 设定为 10px（含安全区），使其恰好嵌入留白空间。 */
.sully-chat-root .flex.items-center.justify-between.bg-slate-50.border-b.border-slate-200.text-slate-500 {
  position: absolute !important;
  left: 46px !important;
  right: 78px !important;
  bottom: calc(10px + env(safe-area-inset-bottom)) !important;
  width: auto !important;
  height: 24px !important;
  background: #EEEEEE !important;
  border: none !important;
  border-radius: 4px !important;
  padding: 0 8px !important;
  margin: 0 !important;
  z-index: 50 !important;
  box-sizing: border-box !important;
  transition: bottom 0.2s ease-out !important;
}

/* 💭 监听底部面板展开状态：面板展开高度为 18rem（288px），将引用条的 bottom 同步增加，使其保持相对位置一致。 */
.sully-chat-root:has(.sully-chat-panel[style*="18rem"]) .flex.items-center.justify-between.bg-slate-50.border-b.border-slate-200.text-slate-500 {
  bottom: calc(288px + 10px + env(safe-area-inset-bottom)) !important;
}

/* 💭 隐藏引用条内的“正在回复:”文本标签。 */
.sully-chat-root .flex.items-center.justify-between.bg-slate-50.border-b.border-slate-200.text-slate-500 .font-bold.text-slate-700 {
  display: none !important;
}

/* 💭 移除左侧内容容器的默认间距，确保剩余文本紧贴左侧边缘。 */
.sully-chat-root .flex.items-center.justify-between.bg-slate-50.border-b.border-slate-200.text-slate-500 .flex.items-center.gap-2 {
  gap: 0 !important;
  margin: 0 !important;
